C = {}
def put(k,l,title,sub,secs): C.setdefault(k,{})[l]=dict(title=title,sub=sub,secs=secs)

# ---------------- 1 SYSTEM ----------------
put("1_System","EN","How unpruuf works","unpruuf system description · status 12 Oct 2026 · NexonAI Consulting SRL",[
("Prerequisite for everything",[("p","Every customer runs their own servers. NexonAI runs none. If a third party hosts the servers, that third party is involved, and the statements in this document no longer apply in the same way."),]),
("The idea in one picture",[("p","Think of a row of private mailboxes. Only the owner can put letters into their own mailbox. Everyone else may only take out what is meant for them. Nobody ever hands a letter directly to another person, and nobody writes on someone else's mailbox."),
 ("p","That is why we say: my server, my rules. I never write to someone else. I put my message on my own server and give my contact what they need to pick it up. It works the same in reverse: my contact leaves a message on their server and I pick it up. Nobody addresses anyone else."),]),
("The two parts",[("b",["The app on the phone. It holds the keys, the contacts and the messages. Everything personal stays on the device.","The customer's own server. It is only a passage, not a filing cabinet. It holds sealed packages for a short time until they are picked up."]),
 ("p","There is no third part. No NexonAI server, no account server, no directory, no push service.")]),
("No identities",[("b",["No user name, no phone number, no e-mail address, no account.","Contacts exist only locally on the device. There is no directory in the system that lists people.","The server cannot say who is behind a package, because nobody ever logs in."])]),
("No direct connections",[("p","Two phones never connect to each other. Each side only talks to a server. Nobody learns the other side's address, and the server never learns who is talking to whom.")]),
("How long things stay",[("b",["Whatever has not been picked up is at most 24 hours old. After that it is gone.","Deletion happens through expiry (maximum 24 hours), not through a restart.","In each chat the user chooses how long their messages wait: 1, 6 or 24 hours."])]),
("What the server knows",[("b",["It holds sealed packages, all of the same size, for a short time.","It cannot read them. It does not know names, phone numbers or who talks to whom.","Anyone who breaks in finds sealed packages that expire anyway. There is no vault worth cracking. A court order to seize the server yields the same: nothing readable, nothing long-lasting, no list of people."])]),
("Three products on one system",[("t",["Product","For whom","What it does"],[
 ["safeline","Companies and institutions with a reporting duty","Anonymous reporting channel with legal deadlines, case numbers and a dashboard for the officer"],
 ["unpruuf Business","Companies, teams, professions handling sensitive content","Internal communication without identities, on the company's own servers"],
 ["safeline Press","Journalists and editorial teams","Tip channel: a QR code on the website, the source writes directly"]])]),
("What the customer gets from us",[("b",["The software for app and server, with install and start scripts (Windows .bat, Linux, Docker).","An offline licence code per server. The code is checked on the customer's own machine and sends nothing to us.","Documentation and, on request, a demonstration after the presentation."])]),
("What the customer does",[("b",["Runs the server (own hardware or own hosting), keeps it updated, restarts it deliberately and unlocks it in the app.","Hands the QR code or the node file to the people who need it.","Decides the organisation: who uses which server, who is the officer, how long things are kept in the product settings."])]),
("Honest status",[("b",["safeline and unpruuf Business are tested and work. An independent audit is pending. Until then: not audited, not certified.","safeline Press is a pilot version and has not been tested with a real source.","The Business app currently has an English interface only. safeline and Press also exist in Romanian.","Not claimed: that the system is unbreakable, certified, or automatically compliant with any law. The organisation remains the controller of its data, and its data protection officer or lawyer confirms the classification."])]),
("Not the right tool if",[("b",["You are legally required to retain every message for years. unpruuf is built so that nothing lingers.","You need group chats or push notifications. They do not exist, by design.","You need to use one identity on several devices. One identity lives on one device."])]),
])
put("1_System","RO","Cum funcționează unpruuf","Descrierea sistemului unpruuf · stare 12 oct. 2026 · NexonAI Consulting SRL",[
("Condiția pentru tot",[("p","Fiecare client își operează propriile servere. NexonAI nu operează niciunul. Dacă serverele sunt găzduite de un terț, acel terț este implicat, iar afirmațiile din acest document nu se mai aplică în același fel.")]),
("Ideea într-o imagine",[("p","Gândiți-vă la un rând de cutii poștale private. Doar proprietarul poate pune scrisori în propria cutie. Ceilalți pot doar să scoată ceea ce le este destinat. Nimeni nu înmânează o scrisoare direct altei persoane și nimeni nu scrie pe cutia altuia."),
 ("p","De aceea spunem: serverul meu, regulile mele. Nu scriu niciodată direct altcuiva. Îmi las mesajul pe propriul server și îi dau contactului ce îi trebuie ca să îl ridice. Invers funcționează la fel: contactul lasă mesajul pe serverul lui, iar eu îl ridic. Nimeni nu adresează pe nimeni.")]),
("Cele două părți",[("b",["Aplicația de pe telefon. Ține cheile, contactele și mesajele. Tot ce e personal rămâne pe dispozitiv.","Serverul propriu al clientului. Este doar un loc de trecere, nu un arhivar. Ține pachete sigilate pentru scurt timp, până sunt ridicate."]),
 ("p","Nu există o a treia parte. Niciun server NexonAI, niciun server de conturi, niciun director, niciun serviciu de notificări push.")]),
("Fără identități",[("b",["Fără nume de utilizator, număr de telefon, adresă de e-mail sau cont.","Contactele există doar local, pe dispozitiv. În sistem nu există un director cu persoane.","Serverul nu poate spune cine se află în spatele unui pachet, pentru că nimeni nu se autentifică vreodată."])]),
("Fără conexiuni directe",[("p","Două telefoane nu se conectează niciodată între ele. Fiecare parte vorbește doar cu un server. Nimeni nu află adresa celeilalte părți, iar serverul nu află cine cu cine vorbește.")]),
("Cât timp rămân lucrurile",[("b",["Ce nu a fost ridicat are cel mult 24 de ore. După aceea dispare.","Ștergerea se face prin expirare (maximum 24 de ore), nu prin repornire.","În fiecare conversație utilizatorul alege cât așteaptă mesajele lui: 1, 6 sau 24 de ore."])]),
("Ce știe serverul",[("b",["Ține pachete sigilate, toate de aceeași mărime, pentru scurt timp.","Nu le poate citi. Nu cunoaște nume, numere de telefon sau cine vorbește cu cine.","Cine sparge serverul găsește pachete sigilate care oricum expiră. Nu există un seif care să merite spart. O hotărâre judecătorească de confiscare a serverului duce la același rezultat: nimic lizibil, nimic de durată, nicio listă de persoane."])]),
("Trei produse pe același sistem",[("t",["Produs","Pentru cine","Ce face"],[
 ["safeline","Companii și instituții cu obligație de raportare","Canal de raportare anonimă cu termene legale, numere de caz și tablou de bord pentru responsabil"],
 ["unpruuf Business","Companii, echipe, profesii care lucrează cu conținut sensibil","Comunicare internă fără identități, pe serverele proprii ale companiei"],
 ["safeline Press","Jurnaliști și redacții","Canal pentru sesizări: un cod QR pe site, sursa scrie direct"]])]),
("Ce primește clientul de la noi",[("b",["Software pentru aplicație și server, cu scripturi de instalare și pornire (Windows .bat, Linux, Docker).","Un cod de licență offline pentru fiecare server. Codul este verificat pe calculatorul clientului și nu trimite nimic către noi.","Documentație și, la cerere, o demonstrație după prezentare."])]),
("Ce face clientul",[("b",["Operează serverul (hardware propriu sau găzduire proprie), îl actualizează, îl repornește deliberat și îl deblochează din aplicație.","Predă codul QR sau fișierul de noduri persoanelor care au nevoie de ele.","Decide organizarea: cine folosește ce server, cine este responsabilul, cât se păstrează lucrurile în setările produsului."])]),
("Stare, spusă deschis",[("b",["safeline și unpruuf Business sunt testate și funcționează. Un audit independent urmează. Până atunci: neauditat, necertificat.","safeline Press este o versiune pilot și nu a fost testată cu o sursă reală.","Aplicația Business are momentan doar interfață în engleză. safeline și Press există și în română.","Nu pretindem: că sistemul este de nesparsit, certificat sau conform automat cu vreo lege. Organizația rămâne operatorul datelor sale, iar încadrarea o confirmă responsabilul cu protecția datelor sau avocatul."])]),
("Nu este instrumentul potrivit dacă",[("b",["Aveți obligația legală de a păstra fiecare mesaj ani la rând. unpruuf este construit astfel încât nimic să nu rămână.","Aveți nevoie de conversații de grup sau de notificări push. Nu există, intenționat.","Aveți nevoie de aceeași identitate pe mai multe dispozitive. O identitate trăiește pe un singur dispozitiv."])]),
])
put("1_System","DE","Wie unpruuf funktioniert","Systembeschreibung unpruuf · Stand 12.10.2026 · NexonAI Consulting SRL",[
("Voraussetzung für alles",[("p","Jeder Kunde betreibt seine eigenen Server. NexonAI betreibt keinen. Hostet ein Dritter die Server, ist dieser Dritte eingebunden, und die Aussagen in diesem Dokument gelten so nicht mehr.")]),
("Die Idee in einem Bild",[("p","Stell dir eine Reihe privater Briefkästen vor. Nur der Besitzer kann Briefe in seinen eigenen Kasten legen. Alle anderen dürfen nur herausnehmen, was für sie bestimmt ist. Niemand übergibt einen Brief direkt an einen anderen, und niemand schreibt an den Kasten eines anderen."),
 ("p","Darum sagen wir: mein Server, meine Regeln. Ich schreibe nie direkt an jemanden. Ich lege meine Nachricht auf meinem eigenen Server ab und gebe dem Kontakt, was er zum Abholen braucht. Umgekehrt genauso. Niemand adressiert andere.")]),
("Die zwei Teile",[("b",["Die App auf dem Telefon. Sie hält Schlüssel, Kontakte und Nachrichten. Alles Persönliche bleibt auf dem Gerät.","Der eigene Server des Kunden. Er ist nur ein Durchgang, keine Ablage. Er hält versiegelte Pakete kurz, bis sie abgeholt werden."]),
 ("p","Einen dritten Teil gibt es nicht. Kein NexonAI-Server, kein Konto-Server, kein Verzeichnis, kein Push-Dienst.")]),
("Keine Identitäten",[("b",["Kein Benutzername, keine Telefonnummer, keine E-Mail, kein Konto.","Kontakte gibt es nur lokal auf dem Gerät, ohne Verzeichnis im System.","Der Server kann nicht sagen, wer hinter einem Paket steckt, weil sich nie jemand anmeldet."])]),
("Keine direkten Verbindungen",[("p","Zwei Telefone verbinden sich nie miteinander. Jede Seite spricht nur mit einem Server. Niemand erfährt die Adresse der anderen Seite, und der Server erfährt nicht, wer mit wem spricht.")]),
("Wie lange etwas bleibt",[("b",["Was nicht abgeholt wurde, ist höchstens 24 Stunden alt. Danach ist es weg.","Gelöscht wird durch Ablauf (höchstens 24 Stunden), nicht durch einen Neustart.","In jedem Chat wählt der Nutzer, wie lange seine Nachrichten warten: 1, 6 oder 24 Stunden."])]),
("Was der Server weiß",[("b",["Er hält versiegelte Pakete gleicher Größe, kurz.","Er kann sie nicht lesen. Er kennt keine Namen, keine Nummern und nicht, wer mit wem spricht.","Wer einbricht, findet Datenmüll, der ohnehin abläuft. Es gibt keinen Tresor, der sich zu knacken lohnt. Ein richterlicher Beschluss zur Beschlagnahme bringt dasselbe: nichts Lesbares, nichts Langlebiges, keine Personenliste."])]),
("Drei Produkte auf einem System",[("t",["Produkt","Für wen","Was es tut"],[
 ["safeline","Firmen und Institutionen mit Meldepflicht","Anonymer Meldekanal mit gesetzlichen Fristen, Fallnummern und Dashboard für die Meldestelle"],
 ["unpruuf Business","Firmen, Teams, Berufe mit sensiblen Inhalten","Interne Kommunikation ohne Identitäten auf den eigenen Servern der Firma"],
 ["safeline Press","Journalisten und Redaktionen","Hinweiskanal: QR-Code auf der Seite, die Quelle schreibt direkt"]])]),
("Was der Kunde von uns bekommt",[("b",["Software für App und Server mit Install- und Start-Skripten (Windows .bat, Linux, Docker).","Pro Server einen Offline-Lizenzcode. Er wird auf dem Rechner des Kunden geprüft und sendet nichts an uns.","Dokumentation und auf Wunsch eine Demonstration nach dem Vortrag."])]),
("Was der Kunde selbst tut",[("b",["Server betreiben (eigene Hardware oder eigenes Hosting), aktuell halten, bewusst neu starten und in der App entsperren.","QR-Code oder Node-Datei an die Leute geben, die sie brauchen.","Organisation festlegen: wer welchen Server nutzt, wer die Meldestelle ist, wie lange etwas in den Produkteinstellungen gehalten wird."])]),
("Ehrlicher Stand",[("b",["safeline und unpruuf Business sind getestet und funktionieren. Ein unabhängiges Audit steht an. Bis dahin: nicht auditiert, nicht zertifiziert.","safeline Press ist eine Pilotversion und nicht mit einer echten Quelle getestet.","Die Business-App hat heute nur eine englische Oberfläche. safeline und Press gibt es auch auf Rumänisch.","Nicht behauptet: unknackbar, zertifiziert oder automatisch gesetzeskonform. Die Organisation bleibt Verantwortliche für ihre Daten, die Einordnung bestätigt der Datenschutzbeauftragte oder ein Jurist."])]),
("Nicht das richtige Werkzeug, wenn",[("b",["Du gesetzlich jede Nachricht jahrelang aufbewahren musst. unpruuf ist so gebaut, dass nichts liegen bleibt.","Du Gruppenchats oder Push-Benachrichtigungen brauchst. Es gibt sie bewusst nicht.","Du eine Identität auf mehreren Geräten brauchen würdest. Eine Identität lebt auf genau einem Gerät."])]),
])
